package eras

import "testing"

// Code generated by temp/gen_eras_anchors.py — the expected values
// were computed by the PYTHON implementation (analysis/lib/eras.py,
// the source of truth), pinning the Go port by construction.
func TestGoldenAgainstPython(t *testing.T) {
	 golden := []Result{
		{true, "2006-08-26", 2006, "interp", "exact"},
		{true, "2006-08-26", 2006, "interp", "exact"},
		{false, "2009-02-04", 2009, "interp", "mid"},
		{true, "2016-04-20", 2016, "interp", "exact"},
		{false, "2017-09-30", 2017, "interp", "mid"},
		{false, "2019-04-16", 2019, "interp", "mid"},
		{false, "2020-03-12", 2020, "interp", "high"},
		{false, "2020-12-03", 2020, "interp", "high"},
		{false, "2021-11-06", 2021, "interp", "high"},
		{false, "2022-11-04", 2022, "interp", "high"},
		{false, "2024-05-01", 2024, "interp", "mid"},
		{false, "2026-11-07", 2026, "extrap_high", "low"},
		{false, "2026-12-21", 2026, "extrap_high", "low"},
		{false, "2027-01-10", 2027, "extrap_high", "low"},
		{false, "2027-01-29", 2027, "extrap_high", "low"},
		{false, "2027-03-06", 2027, "extrap_high", "low"},
	 }
	 probe := []int64{2242, 2243, 5000, 48704, 100000, 200000, 300000, 400000, 500000, 600000, 700000, 800000, 900000, 950000, 1000000, 1100000}
	 for i, want := range golden {
		 got := Estimate(probe[i])
		 if got.EstDate != want.EstDate {
			 t.Errorf("nid %d: est_date = %s, want %s", probe[i], got.EstDate, want.EstDate)
		 }
		 if got.EstYear != want.EstYear {
			 t.Errorf("nid %d: est_year = %d, want %d", probe[i], got.EstYear, want.EstYear)
		 }
		 if got.Mode != want.Mode {
			 t.Errorf("nid %d: mode = %s, want %s", probe[i], got.Mode, want.Mode)
		 }
		 if got.Confidence != want.Confidence {
			 t.Errorf("nid %d: confidence = %s, want %s", probe[i], got.Confidence, want.Confidence)
		 }
	 }
}
